17	typedef struct rbnode {
18	    char *key;               /* owned copy; NULL on the nil sentinel */
19	    void *value;              /* owned iff value_free != NULL */
20	    struct rbnode *left;
21	    struct rbnode *right;
22	    struct rbnode *parent;
23	    enum { RB_RED, RB_BLACK } color;
24	} rbnode_t;
