33	rbtree_t *rb_create(rb_value_free_fn value_free)
34	{
35	    rbtree_t *t = rb_malloc(sizeof *t);
36	    if (!t)
37	        return NULL;                 /* nothing allocated yet, nothing to free */
38	
39	    rbnode_t *nil = rb_malloc(sizeof *nil);
40	    if (!nil)
